import pandas as pd

def clean(df):
    df = df.copy()
    # strip whitespace from object columns
    obj_cols = df.select_dtypes(include='object').columns
    for c in obj_cols:
        df[c] = df[c].astype(str).str.strip()
    # standardise sex case and keep NaN
    if 'sex' in df:
        df['sex'] = df['sex'].replace({'nan': pd.NA, 'None': pd.NA, '': pd.NA})
        df['sex'] = df['sex'].astype(object).where(df['sex'].isna(), df['sex'].str.lower())
    # species label variant
    if 'species' in df:
        df['species'] = df['species'].replace({'Adeile': 'Adelie'})
    # drop exact duplicate rows then duplicate penguin_id
    df = df.drop_duplicates()
    if 'penguin_id' in df:
        df = df.drop_duplicates(subset=['penguin_id'], keep='first')
    # coerce numeric columns that may be stored as text
    num_cols = ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']
    for c in num_cols:
        if c in df:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    # fix obvious out-of-range body_mass_g (e.g., 4,850,000 -> 4,850)
    if 'body_mass_g' in df:
        mask = df['body_mass_g'] > 6500
        df.loc[mask, 'body_mass_g'] = df.loc[mask, 'body_mass_g'] / 1000.0
    return df

def answer(df):
    dfc = clean(df)
    allowed = {'Biscoe', 'Dream', 'Torgersen'}
    counts = dfc.groupby('island').size()
    counts = {k: int(v) for k, v in counts.items() if k in allowed and pd.notna(k)}
    return counts
